#!/usr/bin/env node
/**
 * `pnpm configure` — write a .env with the three generated secrets already filled in.
 *
 * These three are pure entropy: there is nothing to decide, nothing to look up, and no reason a
 * human should be running `openssl` three times and pasting the results into the right lines.
 * The two that *are* decisions — the Google client ID and secret — cannot be generated by
 * anybody but you, so this script names them and stops.
 *
 * Safe to run repeatedly. It never overwrites a value that is already set, because
 * TOKEN_ENCRYPTION_KEY in particular is the difference between "your stored Google token still
 * decrypts" and "everyone re-authorises".
 */

import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { createInterface } from 'node:readline';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const envPath = join(root, '.env');
const examplePath = join(root, '.env.example');

/** URL-safe, no padding — it travels in an Authorization header and in Shortcut config. */
const base64url = (bytes) => randomBytes(bytes).toString('base64url');
/** Standard base64: the vault decodes exactly 32 bytes from this. */
const base64 = (bytes) => randomBytes(bytes).toString('base64');

const GENERATED = {
  INGEST_TOKEN: () => base64url(32),
  TOKEN_ENCRYPTION_KEY: () => base64(32),
  SESSION_SECRET: () => base64(32),
};

const MANUAL = {
  GOOGLE_CLIENT_ID: 'ends in .apps.googleusercontent.com',
  GOOGLE_CLIENT_SECRET: 'starts with GOCSPX-',
};

const bold = (s) => `\u001b[1m${s}\u001b[0m`;
const dim = (s) => `\u001b[2m${s}\u001b[0m`;
const green = (s) => `\u001b[32m${s}\u001b[0m`;
const yellow = (s) => `\u001b[33m${s}\u001b[0m`;

function valueOf(contents, key) {
  // Last assignment wins, matching how dotenv loaders behave.
  const matches = [...contents.matchAll(new RegExp(`^${key}=(.*)$`, 'gm'))];
  return matches.at(-1)?.[1]?.trim() ?? undefined;
}

function setValue(contents, key, value) {
  const line = `${key}=${value}`;
  return new RegExp(`^${key}=.*$`, 'm').test(contents)
    ? contents.replace(new RegExp(`^${key}=.*$`, 'm'), () => line)
    : `${contents.trimEnd()}\n${line}\n`;
}

/**
 * Ask a question on the terminal.
 *
 * `hidden` suppresses the echo, so a pasted client secret never appears on screen, in a
 * scrollback buffer, or in a screen share. It is still written to .env — that file is the
 * point — but there is no reason for it to be visible on the way there.
 */
function ask(question, { hidden = false } = {}) {
  return new Promise((resolve) => {
    const rl = createInterface({ input: process.stdin, output: process.stdout, terminal: true });
    if (hidden) {
      // readline writes the prompt through this hook; echo everything until the prompt has
      // been printed, then nothing, so the typed characters are swallowed.
      let promptShown = false;
      rl._writeToOutput = (chunk) => {
        if (!promptShown) {
          rl.output.write(chunk);
          if (chunk.includes(question)) promptShown = true;
        }
      };
    }
    rl.question(question, (answer) => {
      if (hidden) rl.output.write('\n');
      rl.close();
      resolve(answer.trim());
    });
  });
}

/**
 * Does this look like a value Google actually issued, or like something copied off a screen?
 *
 * The console renders the client secret masked — `****nI43` — and selecting that text with a
 * mouse yields the asterisks, not the secret. It is accepted silently by everything until
 * Google rejects the token exchange, three steps and one browser round-trip later. Catching
 * the shape here turns a baffling failure into a sentence.
 */
function describeBadSecret(value) {
  if (/^\*+/.test(value) || value.includes('****')) {
    return "that is the masked value Google shows on screen, not the secret itself — use the copy button beside it rather than selecting the text";
  }
  if (!value.startsWith('GOCSPX-')) return 'a Google client secret starts with GOCSPX-';
  if (value.length < 24) return `that is only ${value.length} characters; they are around 35`;
  return null;
}

function describeBadClientId(value) {
  if (/^\*+/.test(value) || value.includes('****')) {
    return 'that looks like a masked value — use the copy button rather than selecting the text';
  }
  if (!value.endsWith('.apps.googleusercontent.com')) {
    return 'a Google client ID ends in .apps.googleusercontent.com';
  }
  return null;
}

/** Ask until the answer looks right, or the user insists, or they skip with Enter. */
async function askUntilValid(prompt, validate, { hidden = false } = {}) {
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const value = await ask(prompt, { hidden });
    if (!value) return '';
    const problem = validate(value);
    if (!problem) return value;
    console.log(`  ${yellow('✗')} ${problem}`);
    if (attempt === 2) {
      console.log(`  ${dim('Saving it anyway — correct it in .env if this was deliberate.')}`);
      return value;
    }
    console.log(`  ${dim('Try again, or press Enter to skip.')}`);
  }
  return '';
}

/**
 * Fill in the two Google values by asking, rather than telling someone to open a text editor.
 *
 * Only when attached to a terminal: piped or CI runs fall through to the printed instructions,
 * so nothing ever hangs waiting for input that will not come.
 */
async function promptForGoogle(contents) {
  if (!process.stdin.isTTY) return contents;

  // A value that is present but malformed is worse than a missing one — it looks done and
  // fails later — so offer to replace it rather than treating "set" as "settled".
  const existingSecret = valueOf(contents, 'GOOGLE_CLIENT_SECRET');
  const existingId = valueOf(contents, 'GOOGLE_CLIENT_ID');
  const secretProblem = existingSecret ? describeBadSecret(existingSecret) : null;
  const idProblem = existingId ? describeBadClientId(existingId) : null;

  const needsId = !existingId || idProblem;
  const needsSecret = !existingSecret || secretProblem;
  if (!needsId && !needsSecret) return await promptForLlm(await askPublishingStatus(contents));

  console.log(`\n  ${bold('Two values only your Google account has.')}`);
  console.log(
    `  ${dim('Both are on https://console.cloud.google.com/auth/clients → your OAuth client.')}`,
  );
  console.log(`  ${dim('Use the copy button beside each one; selecting the text can give you a')}`);
  console.log(`  ${dim('masked placeholder instead. Press Enter to skip and fill in by hand.')}\n`);

  if (needsId) {
    if (idProblem) console.log(`  ${yellow('! The client ID in .env looks wrong:')} ${idProblem}`);
    const id = await askUntilValid('  Client ID (ends .apps.googleusercontent.com): ', describeBadClientId);
    if (id) contents = setValue(contents, 'GOOGLE_CLIENT_ID', id);
  }

  if (needsSecret) {
    if (secretProblem) {
      console.log(`  ${yellow('! The client secret in .env looks wrong:')} ${secretProblem}`);
    }
    const secret = await askUntilValid(
      '  Client secret (hidden as you type, starts GOCSPX-): ',
      describeBadSecret,
      { hidden: true },
    );
    if (secret) {
      contents = setValue(contents, 'GOOGLE_CLIENT_SECRET', secret);
      console.log(`  ${green('✓')} saved to .env, never printed`);
    }
  }

  return await promptForLlm(await askPublishingStatus(contents));
}

/**
 * Tier 2: the LLM that turns "that Veritasium one about planes" into a search query.
 *
 * Entirely optional — Tiers 0 and 1 handle any share whose text contains a YouTube link, which
 * is most of them. Asked about only when not already configured, so re-running does not nag.
 */
async function promptForLlm(contents) {
  if (!process.stdin.isTTY) return contents;
  const provider = valueOf(contents, 'LLM_PROVIDER');
  if (provider && provider !== 'none') return contents;
  if (valueOf(contents, 'GEMINI_API_KEY')) return contents;

  console.log(`\n  ${bold('Optional: resolve videos that are described but not linked.')}`);
  console.log(`  ${dim('A Reel saying "that Kurzgesagt one about black holes" with no URL needs a')}`);
  console.log(`  ${dim('language model to turn it into a search. Free key, ~3 minutes:')}`);
  console.log(`  ${dim('https://aistudio.google.com/apikey  → "Create API key"')}`);
  console.log(`  ${dim('Press Enter to skip — everything else works without it.')}\n`);

  const key = await askUntilValid(
    '  Gemini API key (hidden as you type, starts AIza): ',
    (v) => {
      if (/^\*+/.test(v) || v.includes('****')) return 'that looks like a masked value — use the copy button';
      if (!v.startsWith('AIza')) return 'a Google API key starts with AIza';
      if (v.length < 30) return `that is only ${v.length} characters; they are around 39`;
      return null;
    },
    { hidden: true },
  );

  if (!key) {
    console.log(`  ${dim('Skipped. Shares without a link will say so rather than guess.')}`);
    return contents;
  }

  contents = setValue(contents, 'GEMINI_API_KEY', key);
  contents = setValue(contents, 'LLM_PROVIDER', 'gemini');
  console.log(`  ${green('✓')} saved, LLM_PROVIDER set to gemini`);
  return contents;
}

async function askPublishingStatus(contents) {
  // Not cosmetic: left at `testing`, a published app shows a permanent "expires in 7 days"
  // warning that is false, and a warning that cries wolf is one nobody reads when it is real.
  const published = await ask(
    `\n  Have you published the OAuth app to Production? ${dim('(y/N)')} `,
  );
  return setValue(
    contents,
    'GOOGLE_OAUTH_PUBLISHING_STATUS',
    /^y/i.test(published) ? 'production' : 'testing',
  );
}

async function main() {
  if (!existsSync(examplePath)) {
    console.error('.env.example is missing — are you in the repository root?');
    process.exit(1);
  }

  const created = !existsSync(envPath);
  let contents = created ? readFileSync(examplePath, 'utf8') : readFileSync(envPath, 'utf8');

  console.log(`\n  ${bold('Later — setup')}\n`);
  if (created) console.log(`  Created ${bold('.env')} from .env.example\n`);
  else console.log(`  Found an existing ${bold('.env')}. Nothing already set will be changed.\n`);

  for (const [key, make] of Object.entries(GENERATED)) {
    if (valueOf(contents, key)) {
      console.log(`  ${dim('·')} ${key.padEnd(22)} ${dim('already set, left alone')}`);
      continue;
    }
    contents = setValue(contents, key, make());
    console.log(`  ${green('✓')} ${key.padEnd(22)} ${green('generated')}`);
  }

  contents = await promptForGoogle(contents);
  writeFileSync(envPath, contents, { mode: 0o600 });

  const missing = Object.keys(MANUAL).filter((key) => !valueOf(contents, key));

  if (missing.length === 0) {
    console.log(`\n  ${green('Everything required is set.')} Deploy it with:\n`);
    console.log(`      ${bold('pnpm exec wrangler login')}   ${dim('— opens a browser, once')}`);
    console.log(`      ${bold('pnpm deploy:cloudflare')}\n`);
    console.log(`  ${dim('Or run it locally first:')} ${bold('pnpm dev')}\n`);
    return;
  }

  console.log(`\n  ${yellow('Still missing:')}\n`);
  for (const key of missing) console.log(`      ${bold(key.padEnd(22))} ${dim(MANUAL[key])}`);
  console.log(`
  They come from a Google Cloud OAuth client, which only exists inside your own
  Google account. Creating one is free, takes about 15 minutes, needs no card,
  and the exact click path is in:

      ${bold('docs/ACTION-REQUIRED.md')}  ${dim('— Batch 1')}

  Add them to ${bold('.env')} by hand, or run ${bold('pnpm configure')} again to be asked.

  ${bold('Want to see Later work before doing any of that?')} You do not need them:

      ${bold('USE_FIXTURES=true pnpm dev')}

  That runs the whole pipeline against recorded responses. Nothing reaches
  Google, no credentials exist, and no real playlist is touched.
`);
}

await main();
